"""Small reviewed edits on frozen bodies; never visit autogenerated preambles."""
import json
import re
import run as C

S = C.S
previous = C.load('prior_revision', C.PRIOR / 'revise.py')
changes = []
for path in json.loads((C.HERE / 'scope.json').read_text())['paths']:
    file = S.ROOT / path
    before = file.read_text()
    original = S.subprocess.check_output(['git', 'show', f"{json.loads((C.HERE/'scope.json').read_text())['head']}:{path}"], cwd=S.ROOT, text=True)
    wanted = {r['sha256'] for r in json.loads((S.OUT/'bodies.json').read_text()) if r['path'] == path}
    selected = {i for i, r in enumerate(S.spans(path, original)) if r['sha256'] in wanted}
    edits = []
    for i, row in enumerate(S.spans(path, before)):
        if i not in selected or row['language'] != 'kotlin' or row.get('property') == 'preamble':
            continue
        code, count = previous.literals(row['code'])
        code = code.replace('display("selected example", "<div style=\'padding:12px;width:440px\'><b>${e.title}</b><p>${e.description}</p></div>")', 'markdown("selected example", "### ${e.title}\\n\\n${e.description}")')
        if 'val s = centre.sampleSeries(17)[i]' in code:
            code = re.sub(r'\(0\.\.16\)\.map \{ i ->\s*val s = centre\.sampleSeries\(17\)\[i\]', 'centre.sampleSeries(17).map { s ->', code)
            start = code.index('lines(', code.index('val circles'))
            a = code.index('listOf(', start) + len('listOf')
            b = previous.R.close(code, a)
            code = code[:start] + 'val outlines: List<FLine> = [' + code[a+1:b] + ']\nlines(\n    circles + outlines' + code[b+1:]
            count += 1
        if code != row['code']:
            if row['kind'] == 'yaml':
                code = '|\n' + ''.join(' '*row['indent'] + line + '\n' if line else '\n' for line in code.rstrip('\n').splitlines())
            else:
                code = code.rstrip() + '\n'
            edits.append((row['start'], row['end'], code))
            changes.append(dict(path=path, body=i, collectionFactoriesRemoved=count))
    for a, b, code in sorted(edits, reverse=True):
        before = before[:a] + code + before[b:]
    file.write_text(before)
(C.HERE/'revision-verification.json').write_text(json.dumps(dict(changes=changes), indent=2)+'\n')
print(len(changes), 'reviewed bodies updated')
